class Solution {
public:
    int maxSubstrings(string word) {
        int first[26];fill(first,first+26,-1);
        int count=0;
        for (int i=0;i<(int)word.size();++i) {
            int c=word[i]-'a';
            if (first[c]!=-1 && i-first[c]>=3) {
                ++count;
                fill(first,first+26,-1);
            } else if (first[c]==-1) first[c]=i;
        }
        return count;
    }
};
